"""Information Systems, units 1-4: strategy and governance, enterprise architecture, systems analysis and delivery,
and data and analytics management. Two question types for every objective, the quantitative ones recomputed by the
verifier and the classification ones authored multiple choice from the framework's own essential knowledge.

The framework rests on the MSIS 2016 competency model; the frameworks these cards name (COBIT, ITIL, TOGAF, NIST CSF,
the McFarlan grid, MoSCoW, earned value) are named at the level of what each is for, since none of their texts was read.
"""
from opl_dsl import Q

FILE, FRAMEWORK, PRACTICE = "is-core-1", "information-systems", "P1"
MC = ["{{o1}}", "{{o2}}", "{{o3}}", "{{o4}}"]
ST, AR, DV, DA = "is.strategy", "is.architecture", "is.development", "is.data"


def facts(name, skill, rows, explain):
    return Q(name, skill, "{{q}}", pace="recall",
             cases=[{"q": q, "o1": a, "o2": b, "o3": c, "o4": d} for q, a, b, c, d in rows],
             choice=MC, correct="0", verify="authored", explain=explain)


