     verify="Max(nsimplify(v1) + nsimplify(v2) if c1 + c2 <= bg else 0, nsimplify(v1) + nsimplify(v3) if c1 + c3 <= bg else 0, nsimplify(v2) + nsimplify(v3) if c2 + c3 <= bg else 0, nsimplify(v1) if c1 <= bg else 0, nsimplify(v2) if c2 <= bg else 0, nsimplify(v3) if c3 <= bg else 0)",
